function initializeCartFunctionality() {
    let cartCount = 0;
    const cartCountEl = document.querySelector('.cart-count');
    const cartNotification = document.getElementById('cartNotification');
    const notificationText = document.getElementById('notificationText');

    const addToCartButtons = document.querySelectorAll('.add-to-cart-btn');
    addToCartButtons.forEach(button => {
        button.addEventListener('click', function(e) {
            e.stopPropagation();
            cartCount++;
            cartCountEl.textContent = cartCount;

            const productCard = this.closest('.product-card');
            const productName = productCard.querySelector('.product-info h3').textContent;
            const productPrice = productCard.getAttribute('data-price');

            notificationText.textContent = `${productName} added to cart!`;
            showNotification();

            this.style.transform = 'scale(1.15)';
            setTimeout(() => {
                this.style.transform = '';
            }, 200);
        });
    });

    const cartBtn = document.querySelector('.cart-btn');
    cartBtn.addEventListener('click', function() {
        alert(`Cart: ${cartCount} items`);
    });
}

function initializeNewsletterForm() {
    const form = document.getElementById('newsletterForm');
    form.addEventListener('submit', function(e) {
        e.preventDefault();
        const email = form.querySelector('input[type="email"]').value;

        if (email) {
            showNotification('Subscribed successfully!');
            form.reset();
        }
    });
}

function showNotification(message = null) {
    const notification = document.getElementById('cartNotification');
    if (message) {
        document.getElementById('notificationText').textContent = message;
    }

    notification.classList.add('show');
    setTimeout(() => {
        notification.classList.remove('show');
    }, 3000);
}

function initializeScrollAnimations() {
    const observerOptions = {
        threshold: 0.1,
        rootMargin: '0px 0px -50px 0px'
    };

    const observer = new IntersectionObserver(function(entries) {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.style.opacity = '1';
                entry.target.style.transform = 'translateY(0)';
            }
        });
    }, observerOptions);

    const productCards = document.querySelectorAll('.product-card');
    const dealCards = document.querySelectorAll('.deal-card');
    const editorialCards = document.querySelectorAll('.editorial-card');

    [productCards, dealCards, editorialCards].forEach(collection => {
        collection.forEach((element, index) => {
            element.style.opacity = '0';
            element.style.transform = 'translateY(20px)';
            element.style.transition = `opacity 0.5s ease ${index * 0.1}s, transform 0.5s ease ${index * 0.1}s`;
            observer.observe(element);
        });
    });
}

function initializeInteractiveElements() {
    const searchBtn = document.querySelector('.search-btn');
    searchBtn.addEventListener('click', function() {
        const query = prompt('Search for products...');
        if (query) {
            showNotification(`Searching for "${query}"...`);
        }
    });

    const editorialLinks = document.querySelectorAll('.read-more');
    editorialLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            const title = this.closest('.editorial-card').querySelector('h3').textContent;
            showNotification(`Loading: ${title}`);
        });
    });

    const dealButtons = document.querySelectorAll('.deal-card .btn-secondary');
    dealButtons.forEach(button => {
        button.addEventListener('click', function() {
            showNotification('Opening deal...');
        });
    });

    const shopNowBtn = document.querySelector('.hero .btn-primary');
    shopNowBtn.addEventListener('click', function() {
        document.getElementById('featured').scrollIntoView({ behavior: 'smooth' });
    });
}

document.addEventListener('scroll', function() {
    const header = document.querySelector('header');
    if (window.scrollY > 50) {
        header.style.boxShadow = '0 4px 12px rgba(0, 0, 0, 0.3)';
    } else {
        header.style.boxShadow = 'none';
    }
});
